      "home.sections.0.architecture.runtime.tvms.2": "TVM",
      "home.sections.0.architecture.runtime.vm": "GLVM",
      "home.sections.0.architecture.world.items.0": "サービス / エージェント<br>登録・探索",
      "home.sections.0.architecture.world.items.1": "サービス / エージェント編成",
      "home.sections.0.architecture.world.items.2": "プログラム可能なケイパビリティ",
      "home.sections.0.architecture.world.label": "レイヤー 3",
      "home.sections.0.architecture.world.title": "ワールド OS",
      "home.sections.0.eyebrow": "仮想マシン抽象化",
      "home.sections.0.text": "GLVM は、多数の TVM をまたぐ一つの並行実行モデルを開発者に提供します。現在の基盤は ALUX のチェーンランタイムです。次の統合対象はプライベートクラウドで、クライアントデバイスへの展開はロードマップ段階です。",
      "home.sections.0.title": "一つの論理実行レイヤー。<br>物理的には分散。",
      "home.sections.10.eyebrow": "詳しくはこちら",
      "home.sections.10.items.0.0": "GitHub",
      "home.sections.10.items.1.0": "Medium",
