      "glvm.stack.items.4.status": "核心运行时",
      "glvm.stack.items.4.text": "已记录的非确定性选择与执行轨迹，使验证者能够重放被接受的路径。",
      "glvm.stack.items.4.title": "ReplayTrie · 执行轨迹",
      "glvm.stack.items.5.label": "网络",
      "glvm.stack.items.5.status": "核心运行时",
      "glvm.stack.items.5.text": "节点层在执行抽象之下传递提案、区块、状态证据，并协调验证者。",
      "glvm.stack.items.5.title": "对等节点与验证者网络",
